import React from "react";
import { getGoogleLoginUrl } from "../services/api";

function LoginPage() {
  return (
    <div style={{ maxWidth: 720, margin: "0 auto", padding: "3rem 1rem" }}>
      <h1>Sign in</h1>
      <p>Use Google OAuth 2.0 to access the application.</p>
      <a
        href={getGoogleLoginUrl()}
        style={{
          display: "inline-block",
          marginTop: "1rem",
          padding: "0.75rem 1rem",
          background: "#111827",
          color: "#fff",
          borderRadius: 8,
          textDecoration: "none"
        }}
      >
        Continue with Google
      </a>
    </div>
  );
}

export default LoginPage;
